import { createHash, randomUUID } from "node:crypto";
import { createWriteStream } from "node:fs";
import { mkdir, open, readdir, rename, rm, rmdir, unlink, type FileHandle } from "node:fs/promises";
import { dirname, join, sep } from "node:path";
import type { Readable } from "node:stream";
import { Transform } from "node:stream";
import { pipeline } from "node:stream/promises";

/** Longest file name component most Linux file systems accept, in bytes. */
const MAX_SEGMENT_BYTES = 255;

export interface BlobMeta {
  key: string;
  size: number;
  sha256: string;
  modified_at: string;
}

export interface PutResult {
  key: string;
  sha256: string;
  size: number;
}

/** The key can't be stored on this server; maps to 400. */
export class InvalidKeyError extends Error {
  override name = "InvalidKeyError";
}

/**
 * Turns the raw (still percent-encoded) part of the request path after
 * `/blobs/` into a blob key, or throws InvalidKeyError. Accepted keys are
 * relative POSIX paths of non-empty, non-dot segments that decode to valid
 * UTF-8 (so lone surrogates are rejected too) and contain no NUL bytes.
 */
export function parseKey(raw: string): string {
  // req.url carries the request-target bytes as latin1 characters.
  const key = decodeUtf8(percentDecode(Buffer.from(raw, "latin1")));
  if (key === undefined) throw new InvalidKeyError("key is not valid UTF-8");
  if (key === "") throw new InvalidKeyError("key is empty");
  if (key.includes("\0")) throw new InvalidKeyError("key contains a NUL byte");
  if (key.startsWith("/")) throw new InvalidKeyError("key must be a relative path");
  for (const segment of key.split("/")) {
    if (segment === "" || segment === "." || segment === "..") {
      throw new InvalidKeyError("key contains an empty, '.' or '..' path segment");
    }
    if (Buffer.byteLength(segment) > MAX_SEGMENT_BYTES) {
      throw new InvalidKeyError("key contains a path segment that is too long");
    }
  }
  return key;
}

/** Strict UTF-8 decoding: undefined rather than replacement characters. */
function decodeUtf8(bytes: Uint8Array): string | undefined {
  try {
    return new TextDecoder("utf-8", { fatal: true, ignoreBOM: true }).decode(bytes);
  } catch {
    return undefined;
  }
}

function percentDecode(input: Buffer): Buffer {
  const out = Buffer.alloc(input.length);
  let n = 0;
  for (let i = 0; i < input.length; i++) {
    const byte = input[i]!;
    if (byte !== 0x25 /* % */) {
      out[n++] = byte;
      continue;
    }
    const hex = input.subarray(i + 1, i + 3).toString("latin1");
    if (!/^[0-9a-fA-F]{2}$/.test(hex)) {
      throw new InvalidKeyError("key contains a malformed percent-escape");
    }
    out[n++] = parseInt(hex, 16);
    i += 2;
  }
  return out.subarray(0, n);
}

/**
 * File system errors that mean "this key can't be a file here" rather than
 * a server fault: the name is too long or unrepresentable, or it collides
 * with an existing key (`a` vs `a/b`).
 */
const KEY_CONFLICT_CODES = new Set(["ENAMETOOLONG", "EILSEQ", "EINVAL", "ENOTDIR", "EISDIR", "EEXIST"]);

/** File system errors that mean "there is no blob under this key". */
const NOT_FOUND_CODES = new Set(["ENOENT", "ENOTDIR", "EISDIR", "ENAMETOOLONG", "EILSEQ", "EINVAL"]);

/**
 * File system errors that mean an entry list() saw in readdir is gone by the
 * time it gets to it: removed, or a directory turned into a file (or vice
 * versa) by concurrent DELETEs and PUTs.
 */
const VANISHED_CODES = new Set(["ENOENT", "ENOTDIR", "EISDIR"]);

/** How often put() retries when its parent directory vanishes under it. */
const MAX_PUT_ATTEMPTS = 10;

const NS_PER_MS = 1_000_000n;

/**
 * Formats a file time as ISO 8601 UTC, rounded to the nearest millisecond the
 * way fs.Stats#mtime is: file systems store a time set with utimes() slightly
 * below the requested millisecond, and truncating would make a client that
 * copies modified_at onto its file see a different time come back.
 */
function isoFromNs(ns: bigint): string {
  const shifted = ns + NS_PER_MS / 2n;
  // Floor division, so times before 1970 round the same way.
  const ms = shifted / NS_PER_MS - (shifted % NS_PER_MS < 0n ? 1n : 0n);
  return new Date(Number(ms)).toISOString();
}

export interface OpenBlob {
  size: number;
  /** Open for reading; the caller is responsible for closing it. */
  handle: FileHandle;
}

interface CachedHash {
  ino: bigint;
  size: bigint;
  mtimeNs: bigint;
  sha256: string;
}

/**
 * Blobs are stored as plain files under `<dataDir>/blobs/<key>`. Uploads are
 * streamed into `<dataDir>/tmp` and renamed into place, so readers only ever
 * see complete files and concurrent PUTs never interleave.
 */
export class BlobStore {
  private readonly blobsDir: string;
  private readonly tmpDir: string;
  /** SHA-256 of listed files, reused while inode, size and mtime match. */
  private hashCache = new Map<string, CachedHash>();

  constructor(dataDir: string) {
    this.blobsDir = join(dataDir, "blobs");
    this.tmpDir = join(dataDir, "tmp");
  }

  async put(key: string, body: Readable): Promise<PutResult> {
    await mkdir(this.tmpDir, { recursive: true });
    const tmp = join(this.tmpDir, randomUUID());
    const hash = createHash("sha256");
    let size = 0;
    try {
      await pipeline(
        body,
        new Transform({
          transform(chunk: Buffer, _encoding, callback) {
            hash.update(chunk);
            size += chunk.length;
            callback(null, chunk);
          },
        }),
        createWriteStream(tmp, { flags: "wx" }),
      );

      const target = this.pathOf(key);
      for (let attempt = 1; ; attempt++) {
        try {
          await mkdir(dirname(target), { recursive: true });
          await rename(tmp, target);
          break;
        } catch (err) {
          const code = (err as NodeJS.ErrnoException).code ?? "";
          if (KEY_CONFLICT_CODES.has(code)) {
            throw new InvalidKeyError(`key cannot be stored: ${(err as Error).message}`);
          }
          // A concurrent delete pruned the parent directory between mkdir
          // and rename: recreate it and try again.
          if (code === "ENOENT" && attempt < MAX_PUT_ATTEMPTS) continue;
          throw err;
        }
      }
    } catch (err) {
      await rm(tmp, { force: true });
      throw err;
    }
    return { key, sha256: hash.digest("hex"), size };
  }

  /** Opens the blob stored under `key`, or returns undefined if there is none. */
  async open(key: string): Promise<OpenBlob | undefined> {
    let handle;
    try {
      handle = await open(this.pathOf(key), "r");
    } catch (err) {
      if (NOT_FOUND_CODES.has((err as NodeJS.ErrnoException).code ?? "")) return undefined;
      throw err;
    }
    try {
      // Directories along a stored key's path (`docs` for `docs/readme.txt`)
      // open fine on Linux but aren't blobs.
      const st = await handle.stat();
      if (!st.isFile()) {
        await handle.close();
        return undefined;
      }
      return { size: st.size, handle };
    } catch (err) {
      await handle.close();
      throw err;
    }
  }

  /** Deletes the blob stored under `key`; returns false if there is none. */
  async delete(key: string): Promise<boolean> {
    const target = this.pathOf(key);
    try {
      await unlink(target);
    } catch (err) {
      // Directories of other keys aren't blobs either; unlink() reports them
      // as EISDIR on Linux and EPERM on some other systems.
      const code = (err as NodeJS.ErrnoException).code ?? "";
      if (NOT_FOUND_CODES.has(code) || code === "EPERM") return false;
      throw err;
    }
    await this.pruneEmptyDirs(dirname(target));
    return true;
  }

  /**
   * Removes directories left empty by a delete, up to (not including) the
   * store root, so that `docs` can be stored as a key again once
   * `docs/readme.txt` is gone. Best effort: stops at the first directory that
   * is not empty or can't be removed.
   */
  private async pruneEmptyDirs(dir: string): Promise<void> {
    while (dir !== this.blobsDir && dir.startsWith(this.blobsDir + sep)) {
      try {
        await rmdir(dir);
      } catch {
        return;
      }
      dir = dirname(dir);
    }
  }

  private pathOf(key: string): string {
    return join(this.blobsDir, ...key.split("/"));
  }

  async list(): Promise<BlobMeta[]> {
    const blobs: BlobMeta[] = [];
    const cache = new Map<string, CachedHash>();
    await this.walk(this.blobsDir, "", blobs, cache);
    this.hashCache = cache;
    return blobs.sort((a, b) => (a.key < b.key ? -1 : a.key > b.key ? 1 : 0));
  }

  private async walk(dir: string, prefix: string, out: BlobMeta[], cache: Map<string, CachedHash>): Promise<void> {
    let entries;
    try {
      // Raw names: decoding them leniently would list keys GET can't find.
      entries = await readdir(dir, { withFileTypes: true, encoding: "buffer" });
    } catch (err) {
      if (VANISHED_CODES.has((err as NodeJS.ErrnoException).code ?? "")) return;
      throw err;
    }
    for (const entry of entries) {
      // A file put into the store from outside may have a name that isn't
      // valid UTF-8; no key can address it, so it isn't a blob.
      const name = decodeUtf8(entry.name);
      if (name === undefined) continue;
      const key = prefix + name;
      const path = join(dir, name);
      if (entry.isDirectory()) {
        await this.walk(path, `${key}/`, out, cache);
      } else if (entry.isFile()) {
        const meta = await this.describe(key, path, cache);
        if (meta !== undefined) out.push(meta);
      }
    }
  }

  private async describe(key: string, path: string, cache: Map<string, CachedHash>): Promise<BlobMeta | undefined> {
    let handle;
    try {
      handle = await open(path, "r");
    } catch (err) {
      if (VANISHED_CODES.has((err as NodeJS.ErrnoException).code ?? "")) return undefined;
      throw err;
    }
    try {
      // Stat and hash through the same handle, so a concurrent overwrite
      // can't pair one version's size with another version's hash.
      const st = await handle.stat({ bigint: true });
      // Replaced by a directory since readdir (which opens fine on Linux).
      if (!st.isFile()) return undefined;
      const cached = this.hashCache.get(key);
      let entry: CachedHash;
      if (cached !== undefined && cached.ino === st.ino && cached.size === st.size && cached.mtimeNs === st.mtimeNs) {
        entry = cached;
      } else {
        const hash = createHash("sha256");
        for await (const chunk of handle.createReadStream({ autoClose: false })) {
          hash.update(chunk as Buffer);
        }
        entry = { ino: st.ino, size: st.size, mtimeNs: st.mtimeNs, sha256: hash.digest("hex") };
      }
      cache.set(key, entry);
      return {
        key,
        size: Number(st.size),
        sha256: entry.sha256,
        modified_at: isoFromNs(st.mtimeNs),
      };
    } finally {
      await handle.close();
    }
  }
}
export const DEFAULT_PORT = 8080;

export interface ServerConfig {
  dataDir: string;
  port: number;
}

export type ParseResult = { kind: "help" } | { kind: "config"; config: ServerConfig };

export class ConfigError extends Error {
  override name = "ConfigError";
}

export const USAGE = `Usage: syncbox-server --data-dir <path> [--port <n>]

Options:
  --data-dir <path>  Directory where blobs are stored (required).
                     Env: SYNCBOX_DATA_DIR
  --port <n>         TCP port to listen on (default ${DEFAULT_PORT}).
                     Env: SYNCBOX_PORT
  -h, --help         Show this help.

Command-line flags take precedence over environment variables.`;

/**
 * Resolves server configuration from command-line arguments and environment.
 * Precedence: flag > environment variable > default. Empty environment
 * variables are treated as unset.
 */
export function parseConfig(argv: readonly string[], env: NodeJS.ProcessEnv): ParseResult {
  let dataDir: string | undefined;
  let portRaw: string | undefined;

  for (let i = 0; i < argv.length; i++) {
    const arg = argv[i]!;
    if (arg === "-h" || arg === "--help") {
      return { kind: "help" };
    }

    const eq = arg.indexOf("=");
    const name = arg.startsWith("--") && eq !== -1 ? arg.slice(0, eq) : arg;
    let value: string | undefined;
    if (name === "--data-dir" || name === "--port") {
      if (eq !== -1 && arg.startsWith("--")) {
        value = arg.slice(eq + 1);
      } else {
        value = argv[++i];
        if (value === undefined) {
          throw new ConfigError(`${name} requires a value`);
        }
      }
    }

    switch (name) {
      case "--data-dir":
        dataDir = value;
        break;
      case "--port":
        portRaw = value;
        break;
      default:
        throw new ConfigError(`unknown argument: ${arg}`);
    }
  }

  dataDir ??= nonEmpty(env.SYNCBOX_DATA_DIR);
  portRaw ??= nonEmpty(env.SYNCBOX_PORT);

  if (dataDir === undefined || dataDir === "") {
    throw new ConfigError("--data-dir is required (or set SYNCBOX_DATA_DIR)");
  }

  const port = portRaw === undefined ? DEFAULT_PORT : parsePort(portRaw);
  return { kind: "config", config: { dataDir, port } };
}

function parsePort(raw: string): number {
  if (!/^[0-9]+$/.test(raw)) {
    throw new ConfigError(`invalid port: ${JSON.stringify(raw)} (expected an integer 1-65535)`);
  }
  const port = Number(raw);
  if (port < 1 || port > 65535) {
    throw new ConfigError(`invalid port: ${raw} (expected an integer 1-65535)`);
  }
  return port;
}

function nonEmpty(value: string | undefined): string | undefined {
  return value === undefined || value === "" ? undefined : value;
}
import { ConfigError, parseConfig, USAGE } from "./config.js";
import { startServer } from "./server.js";

const EXIT_USAGE = 2;

async function main(): Promise<number | undefined> {
  let parsed;
  try {
    parsed = parseConfig(process.argv.slice(2), process.env);
  } catch (err) {
    if (err instanceof ConfigError) {
      console.error(`syncbox-server: ${err.message}\n\n${USAGE}`);
      return EXIT_USAGE;
    }
    throw err;
  }

  if (parsed.kind === "help") {
    console.log(USAGE);
    return 0;
  }

  const { config } = parsed;
  let running;
  try {
    running = await startServer(config);
  } catch (err) {
    console.error(`syncbox-server: failed to start: ${err instanceof Error ? err.message : String(err)}`);
    return 1;
  }

  console.log(`syncbox-server listening on port ${running.port}, data dir ${config.dataDir}`);

  // Node running as PID 1 in a container gets no default signal handlers,
  // so shutdown has to be wired up explicitly.
  const shutdown = (signal: NodeJS.Signals): void => {
    console.log(`syncbox-server: received ${signal}, shutting down`);
    running.close().then(
      () => process.exit(0),
      (err: unknown) => {
        console.error("syncbox-server: error during shutdown:", err);
        process.exit(1);
      },
    );
  };
  process.once("SIGTERM", shutdown);
  process.once("SIGINT", shutdown);
  return undefined;
}

main().then(
  (code) => {
    if (code !== undefined) process.exitCode = code;
  },
  (err: unknown) => {
    console.error("syncbox-server: fatal error:", err);
    process.exit(1);
  },
);
import { constants as fsConstants } from "node:fs";
import { access, mkdir, stat } from "node:fs/promises";
import http from "node:http";
import type { AddressInfo } from "node:net";
import { pipeline } from "node:stream/promises";

import { BlobStore, InvalidKeyError, parseKey } from "./blobs.js";
import type { ServerConfig } from "./config.js";

export interface RunningServer {
  readonly server: http.Server;
  /** Actual port the server is bound to (useful when started with port 0). */
  readonly port: number;
  /** Stops accepting connections and waits for in-flight requests to finish. */
  close(): Promise<void>;
}

export interface StartOptions {
  /** Interface to bind; defaults to all interfaces. */
  host?: string;
  /** How long close() waits for in-flight requests before dropping them. */
  shutdownTimeoutMs?: number;
}

/**
 * Makes sure the data directory exists and is a writable directory, so that
 * misconfiguration is reported at startup rather than on the first request.
 */
export async function prepareDataDir(dataDir: string): Promise<void> {
  await mkdir(dataDir, { recursive: true });
  const info = await stat(dataDir);
  if (!info.isDirectory()) {
    throw new Error(`data dir is not a directory: ${dataDir}`);
  }
  await access(dataDir, fsConstants.R_OK | fsConstants.W_OK);
}

export function createRequestHandler(config: ServerConfig): http.RequestListener {
  const store = new BlobStore(config.dataDir);
  return (req, res) => {
    route(store, req, res).catch((err: unknown) => {
      console.error("unhandled error while serving request:", err);
      if (!res.headersSent) {
        sendJson(res, 500, { error: "internal server error" });
      } else {
        res.destroy();
      }
    });
  };
}

async function route(store: BlobStore, req: http.IncomingMessage, res: http.ServerResponse): Promise<void> {
  // Raw path without the query string. Deliberately not normalized via URL:
  // blob keys must be validated as sent, not after the dot segments have
  // been silently resolved.
  const path = (req.url ?? "").split("?", 1)[0]!;

  if (path === "/healthz") {
    if (req.method === "GET" || req.method === "HEAD") {
      sendJson(res, 200, { status: "ok" });
    } else {
      res.setHeader("Allow", "GET, HEAD");
      sendJson(res, 405, { error: "method not allowed" });
    }
    return;
  }

  if (path === "/blobs") {
    if (req.method === "GET" || req.method === "HEAD") {
      sendJson(res, 200, await store.list());
    } else {
      res.setHeader("Allow", "GET, HEAD");
      sendJson(res, 405, { error: "method not allowed" });
    }
    return;
  }

  if (path.startsWith("/blobs/")) {
    if (req.method !== "PUT" && req.method !== "GET" && req.method !== "HEAD" && req.method !== "DELETE") {
      res.setHeader("Allow", "GET, HEAD, PUT, DELETE");
      sendJson(res, 405, { error: "method not allowed" });
      return;
    }
    try {
      const key = parseKey(path.slice("/blobs/".length));
      if (req.method === "PUT") {
        sendJson(res, 201, await store.put(key, req));
      } else if (req.method === "DELETE") {
        if (await store.delete(key)) {
          res.writeHead(204).end();
        } else {
          sendJson(res, 404, { error: "blob not found" });
        }
      } else {
        await sendBlob(store, key, req, res);
      }
    } catch (err) {
      if (!(err instanceof InvalidKeyError)) throw err;
      sendJson(res, 400, { error: err.message });
    }
    return;
  }

  sendJson(res, 404, { error: "not found" });
}

async function sendBlob(store: BlobStore, key: string, req: http.IncomingMessage, res: http.ServerResponse): Promise<void> {
  const blob = await store.open(key);
  if (blob === undefined) {
    sendJson(res, 404, { error: "blob not found" });
    return;
  }
  res.writeHead(200, {
    "Content-Type": "application/octet-stream",
    "Content-Length": blob.size,
  });
  if (req.method === "HEAD") {
    await blob.handle.close();
    res.end();
    return;
  }
  try {
    // The read stream closes the handle when it ends or fails.
    await pipeline(blob.handle.createReadStream(), res);
  } catch (err) {
    // The client went away mid-download: nothing to report.
    if ((err as NodeJS.ErrnoException).code === "ERR_STREAM_PREMATURE_CLOSE") return;
    throw err;
  }
}

function sendJson(res: http.ServerResponse, status: number, body: unknown): void {
  const payload = JSON.stringify(body);
  res.writeHead(status, {
    "Content-Type": "application/json; charset=utf-8",
    "Content-Length": Buffer.byteLength(payload),
  });
  res.end(payload);
}

export async function startServer(config: ServerConfig, options: StartOptions = {}): Promise<RunningServer> {
  await prepareDataDir(config.dataDir);

  const server = http.createServer(createRequestHandler(config));

  // Malformed HTTP must never take the process down: answer 400 and drop
  // the connection.
  server.on("clientError", (err: NodeJS.ErrnoException, socket) => {
    if (err.code === "ECONNRESET" || !socket.writable) {
      socket.destroy();
      return;
    }
    socket.end("HTTP/1.1 400 Bad Request\r\nConnection: close\r\nContent-Length: 0\r\n\r\n");
  });

  await new Promise<void>((resolve, reject) => {
    server.once("error", reject);
    const onListening = (): void => {
      server.off("error", reject);
      resolve();
    };
    if (options.host === undefined) {
      server.listen(config.port, onListening);
    } else {
      server.listen(config.port, options.host, onListening);
    }
  });

  const shutdownTimeoutMs = options.shutdownTimeoutMs ?? 5000;
  let closing: Promise<void> | undefined;

  return {
    server,
    port: (server.address() as AddressInfo).port,
    close() {
      closing ??= new Promise<void>((resolve, reject) => {
        const timer = setTimeout(() => server.closeAllConnections(), shutdownTimeoutMs);
        timer.unref();
        server.close((err) => {
          clearTimeout(timer);
          if (err) reject(err);
          else resolve();
        });
        server.closeIdleConnections();
      });
      return closing;
    },
  };
}
{
  "name": "syncbox",
  "version": "0.1.0",
  "private": true,
  "description": "Self-hosted file storage with sync: HTTP server + CLI client",
  "type": "module",
  "engines": {
    "node": ">=20 <21"
  },
  "scripts": {
    "build": "tsc -p tsconfig.build.json",
    "build:test": "tsc -p tsconfig.json",
    "test": "node --test --test-reporter=spec dist/test/",
    "start": "node dist/src/main.js"
  },
  "devDependencies": {
    "@types/node": "~20.19.43",
    "typescript": "~5.9.3"
  }
}
#!/usr/bin/env bash
# Builds the test image and runs the whole test suite inside Docker (via
# docker compose). Exits non-zero if any test fails.
set -euo pipefail

repo="$(cd "$(dirname "${BASH_SOURCE[0]}")" && pwd)"

exec docker compose --project-directory "$repo" -f "$repo/compose.yaml" \
  run --rm --build -T test
# syntax=docker/dockerfile:1

# --- dependencies (incl. dev: TypeScript, type definitions) ---------------
FROM node:20-bookworm-slim AS deps
WORKDIR /app
COPY package.json package-lock.json ./
RUN npm ci --no-audit --no-fund

# --- compile server sources -----------------------------------------------
FROM deps AS build
COPY tsconfig.json tsconfig.build.json ./
COPY src ./src
RUN npm run build

# --- test image: compiled sources + compiled tests ------------------------
FROM build AS test
COPY test ./test
RUN npm run build:test
CMD ["npm", "test", "--silent"]

# --- runtime image: production dependencies and compiled server only ------
FROM node:20-bookworm-slim AS server
ENV NODE_ENV=production
WORKDIR /app
COPY package.json package-lock.json ./
RUN npm ci --omit=dev --no-audit --no-fund && npm cache clean --force
COPY --from=build /app/dist/src ./dist/src
USER node
EXPOSE 8080
CMD ["node", "dist/src/main.js"]
# All Docker plumbing for Syncbox lives here. The run-server / run-tests
# wrappers only export the variables below and call `docker compose`.
#
#   SYNCBOX_HOST_DATA_DIR  host directory bind-mounted as the server's data dir
#                          (absolute path; default ./data in the repo)
#   SYNCBOX_PORT           port the server listens on, both in the container
#                          and on the host (default 8080)
#   SYNCBOX_PUBLISH_ADDR   host interface the port is published on
#                          (default 127.0.0.1; set 0.0.0.0 to expose on the LAN)
#   SYNCBOX_UID/GID        user the server runs as, so files in the data dir
#                          are owned by the invoking host user (default 1000)

services:
  server:
    # Fixed tag: run-server uses a separate compose project per port, and
    # they should all share one image rather than each building its own.
    image: syncbox-server:local
    build:
      context: .
      target: server
    init: true
    # Docker's default bridge: no per-project network has to be created, so
    # several servers (on different ports) can be started concurrently.
    network_mode: bridge
    user: "${SYNCBOX_UID:-1000}:${SYNCBOX_GID:-1000}"
    environment:
      SYNCBOX_DATA_DIR: /data
      SYNCBOX_PORT: "${SYNCBOX_PORT:-8080}"
    ports:
