189	  async open(key: string): Promise<OpenBlob | undefined> {
190	    let handle;
191	    try {
192	      handle = await open(this.pathOf(key), "r");
193	    } catch (err) {
194	      if (NOT_FOUND_CODES.has((err as NodeJS.ErrnoException).code ?? "")) return undefined;
195	      throw err;
