125	  size: bigint;
126	  mtimeNs: bigint;
127	  sha256: string;
128	}
129	
130	/**
131	 * Blobs are stored as plain files under `<dataDir>/blobs/<key>`. Uploads are
132	 * streamed into `<dataDir>/tmp` and renamed into place, so readers only ever
133	 * see complete files and concurrent PUTs never interleave.
134	 */
135	export class BlobStore {
136	  private readonly blobsDir: string;
137	  private readonly tmpDir: string;
138	  /** SHA-256 of listed files, reused while inode, size and mtime match. */
139	  private hashCache = new Map<string, CachedHash>();
140	
141	  constructor(dataDir: string) {
142	    this.blobsDir = join(dataDir, "blobs");
143	    this.tmpDir = join(dataDir, "tmp");
144	  }
145	
146	  async put(key: string, body: Readable): Promise<PutResult> {
147	    await mkdir(this.tmpDir, { recursive: true });
148	    const tmp = join(this.tmpDir, randomUUID());
149	    const hash = createHash("sha256");
150	    let size = 0;
151	    try {
152	      await pipeline(
153	        body,
154	        new Transform({
155	          transform(chunk: Buffer, _encoding, callback) {
156	            hash.update(chunk);
157	            size += chunk.length;
158	            callback(null, chunk);
159	          },
160	        }),
161	        createWriteStream(tmp, { flags: "wx" }),
162	      );
163	
164	      const target = this.pathOf(key);
165	      for (let attempt = 1; ; attempt++) {
166	        try {
167	          await mkdir(dirname(target), { recursive: true });
168	          await rename(tmp, target);
169	          break;
170	        } catch (err) {
171	          const code = (err as NodeJS.ErrnoException).code ?? "";
172	          if (KEY_CONFLICT_CODES.has(code)) {
173	            throw new InvalidKeyError(`key cannot be stored: ${(err as Error).message}`);
174	          }
175	          // A concurrent delete pruned the parent directory between mkdir
176	          // and rename: recreate it and try again.
177	          if (code === "ENOENT" && attempt < MAX_PUT_ATTEMPTS) continue;
178	          throw err;
179	        }
180	      }
181	    } catch (err) {
182	      await rm(tmp, { force: true });
183	      throw err;
184	    }
185	    return { key, sha256: hash.digest("hex"), size };
186	  }
187	
188	  /** Opens the blob stored under `key`, or returns undefined if there is none. */
189	  async open(key: string): Promise<OpenBlob | undefined> {
190	    let handle;
191	    try {
192	      handle = await open(this.pathOf(key), "r");
193	    } catch (err) {
194	      if (NOT_FOUND_CODES.has((err as NodeJS.ErrnoException).code ?? "")) return undefined;
195	      throw err;
196	    }
197	    try {
198	      // Directories along a stored key's path (`docs` for `docs/readme.txt`)
199	      // open fine on Linux but aren't blobs.
200	      const st = await handle.stat();
201	      if (!st.isFile()) {
202	        await handle.close();
203	        return undefined;
204	      }
205	      return { size: st.size, handle };
206	    } catch (err) {
207	      await handle.close();
208	      throw err;
209	    }
210	  }
211	
212	  /** Deletes the blob stored under `key`; returns false if there is none. */
213	  async delete(key: string): Promise<boolean> {
214	    const target = this.pathOf(key);
215	    try {
216	      await unlink(target);
217	    } catch (err) {
218	      // Directories of other keys aren't blobs either; unlink() reports them
219	      // as EISDIR on Linux and EPERM on some other systems.
220	      const code = (err as NodeJS.ErrnoException).code ?? "";
221	      if (NOT_FOUND_CODES.has(code) || code === "EPERM") return false;
222	      throw err;
223	    }
224	    await this.pruneEmptyDirs(dirname(target));
225	    return true;
226	  }
227	
228	  /**
229	   * Removes directories left empty by a delete, up to (not including) the
230	   * store root, so that `docs` can be stored as a key again once
231	   * `docs/readme.txt` is gone. Best effort: stops at the first directory that
232	   * is not empty or can't be removed.
233	   */
234	  private async pruneEmptyDirs(dir: string): Promise<void> {
235	    while (dir !== this.blobsDir && dir.startsWith(this.blobsDir + sep)) {
236	      try {
237	        await rmdir(dir);
238	      } catch {
239	        return;
240	      }
241	      dir = dirname(dir);
242	    }
243	  }
244	
245	  private pathOf(key: string): string {
246	    return join(this.blobsDir, ...key.split("/"));
247	  }
248	
249	  async list(): Promise<BlobMeta[]> {
250	    const blobs: BlobMeta[] = [];
251	    const cache = new Map<string, CachedHash>();
252	    await this.walk(this.blobsDir, "", blobs, cache);
253	    this.hashCache = cache;
254	    return blobs.sort((a, b) => (a.key < b.key ? -1 : a.key > b.key ? 1 : 0));
255	  }
256	
257	  private async walk(dir: string, prefix: string, out: BlobMeta[], cache: Map<string, CachedHash>): Promise<void> {
258	    let entries;
259	    try {
260	      // Raw names: decoding them leniently would list keys GET can't find.
261	      entries = await readdir(dir, { withFileTypes: true, encoding: "buffer" });
262	    } catch (err) {
263	      if (VANISHED_CODES.has((err as NodeJS.ErrnoException).code ?? "")) return;
264	      throw err;
265	    }
266	    for (const entry of entries) {
267	      // A file put into the store from outside may have a name that isn't
268	      // valid UTF-8; no key can address it, so it isn't a blob.
269	      const name = decodeUtf8(entry.name);
270	      if (name === undefined) continue;
271	      const key = prefix + name;
272	      const path = join(dir, name);
273	      if (entry.isDirectory()) {
274	        await this.walk(path, `${key}/`, out, cache);
275	      } else if (entry.isFile()) {
276	        const meta = await this.describe(key, path, cache);
277	        if (meta !== undefined) out.push(meta);
278	      }
279	    }
280	  }
281	
282	  private async describe(key: string, path: string, cache: Map<string, CachedHash>): Promise<BlobMeta | undefined> {
283	    let handle;
284	    try {
285	      handle = await open(path, "r");
286	    } catch (err) {
287	      if (VANISHED_CODES.has((err as NodeJS.ErrnoException).code ?? "")) return undefined;
288	      throw err;
289	    }
290	    try {
291	      // Stat and hash through the same handle, so a concurrent overwrite
292	      // can't pair one version's size with another version's hash.
293	      const st = await handle.stat({ bigint: true });
294	      // Replaced by a directory since readdir (which opens fine on Linux).
295	      if (!st.isFile()) return undefined;
296	      const cached = this.hashCache.get(key);
297	      let entry: CachedHash;
298	      if (cached !== undefined && cached.ino === st.ino && cached.size === st.size && cached.mtimeNs === st.mtimeNs) {
299	        entry = cached;
300	      } else {
301	        const hash = createHash("sha256");
302	        for await (const chunk of handle.createReadStream({ autoClose: false })) {
303	          hash.update(chunk as Buffer);
304	        }
305	        entry = { ino: st.ino, size: st.size, mtimeNs: st.mtimeNs, sha256: hash.digest("hex") };
306	      }
307	      cache.set(key, entry);
308	      return {
309	        key,
310	        size: Number(st.size),
311	        sha256: entry.sha256,
312	        modified_at: isoFromNs(st.mtimeNs),
313	      };
314	    } finally {
315	      await handle.close();
316	    }
317	  }
318	}

