    25	/**
    26	 * Makes sure the data directory exists and is a writable directory, so that
    27	 * misconfiguration is reported at startup rather than on the first request.
    28	 */
    29	export async function prepareDataDir(dataDir: string): Promise<void> {
    30	  await mkdir(dataDir, { recursive: true });
    31	  const info = await stat(dataDir);
    32	  if (!info.isDirectory()) {
    33	    throw new Error(`data dir is not a directory: ${dataDir}`);
    34	  }
    35	  await access(dataDir, fsConstants.R_OK | fsConstants.W_OK);
    36	}
