    38	export function createRequestHandler(config: ServerConfig): http.RequestListener {
    39	  const store = new BlobStore(config.dataDir);
    40	  return (req, res) => {
    41	    route(store, req, res).catch((err: unknown) => {
    42	      console.error("unhandled error while serving request:", err);
    43	      if (!res.headersSent) {
    44	        sendJson(res, 500, { error: "internal server error" });
    45	      } else {
    46	        res.destroy();
    47	      }
    48	    });
    49	  };
    50	}
