    52	async function route(store: BlobStore, req: http.IncomingMessage, res: http.ServerResponse): Promise<void> {
    53	  // Raw path without the query string. Deliberately not normalized via URL:
    54	  // blob keys must be validated as sent, not after the dot segments have
    55	  // been silently resolved.
    56	  const path = (req.url ?? "").split("?", 1)[0]!;
    57	
    58	  if (path === "/healthz") {
    59	    if (req.method === "GET" || req.method === "HEAD") {
    60	      sendJson(res, 200, { status: "ok" });
    61	    } else {
    62	      res.setHeader("Allow", "GET, HEAD");
    63	      sendJson(res, 405, { error: "method not allowed" });
    64	    }
    65	    return;
    66	  }
    67	
    68	  if (path === "/blobs") {
    69	    if (req.method === "GET" || req.method === "HEAD") {
    70	      sendJson(res, 200, await store.list());
    71	    } else {
    72	      res.setHeader("Allow", "GET, HEAD");
    73	      sendJson(res, 405, { error: "method not allowed" });
    74	    }
    75	    return;
    76	  }
    77	
    78	  if (path.startsWith("/blobs/")) {
    79	    if (req.method !== "PUT" && req.method !== "GET" && req.method !== "HEAD" && req.method !== "DELETE") {
    80	      res.setHeader("Allow", "GET, HEAD, PUT, DELETE");
    81	      sendJson(res, 405, { error: "method not allowed" });
    82	      return;
    83	    }
    84	    try {
    85	      const key = parseKey(path.slice("/blobs/".length));
    86	      if (req.method === "PUT") {
    87	        sendJson(res, 201, await store.put(key, req));
    88	      } else if (req.method === "DELETE") {
    89	        if (await store.delete(key)) {
    90	          res.writeHead(204).end();
