    92	          sendJson(res, 404, { error: "blob not found" });
    93	        }
    94	      } else {
    95	        await sendBlob(store, key, req, res);
    96	      }
    97	    } catch (err) {
    98	      if (!(err instanceof InvalidKeyError)) throw err;
    99	      sendJson(res, 400, { error: err.message });
   100	    }
   101	    return;
   102	  }
   103	
   104	  sendJson(res, 404, { error: "not found" });
   105	}
   106	
   107	async function sendBlob(store: BlobStore, key: string, req: http.IncomingMessage, res: http.ServerResponse): Promise<void> {
   108	  const blob = await store.open(key);
   109	  if (blob === undefined) {
   110	    sendJson(res, 404, { error: "blob not found" });
   111	    return;
   112	  }
   113	  res.writeHead(200, {
   114	    "Content-Type": "application/octet-stream",
   115	    "Content-Length": blob.size,
   116	  });
   117	  if (req.method === "HEAD") {
   118	    await blob.handle.close();
