   120	    return;
   121	  }
   122	  try {
   123	    // The read stream closes the handle when it ends or fails.
   124	    await pipeline(blob.handle.createReadStream(), res);
   125	  } catch (err) {
   126	    // The client went away mid-download: nothing to report.
   127	    if ((err as NodeJS.ErrnoException).code === "ERR_STREAM_PREMATURE_CLOSE") return;
   128	    throw err;
   129	  }
   130	}
   131	
   132	function sendJson(res: http.ServerResponse, status: number, body: unknown): void {
   133	  const payload = JSON.stringify(body);
   134	  res.writeHead(status, {
   135	    "Content-Type": "application/json; charset=utf-8",
   136	    "Content-Length": Buffer.byteLength(payload),
   137	  });
   138	  res.end(payload);
   139	}
   140	
   141	export async function startServer(config: ServerConfig, options: StartOptions = {}): Promise<RunningServer> {
   142	  await prepareDataDir(config.dataDir);
   143	
   144	  const server = http.createServer(createRequestHandler(config));
   145	
   146	  // Malformed HTTP must never take the process down: answer 400 and drop
   147	  // the connection.
   148	  server.on("clientError", (err: NodeJS.ErrnoException, socket) => {
   149	    if (err.code === "ECONNRESET" || !socket.writable) {
   150	      socket.destroy();
   151	      return;
   152	    }
   153	    socket.end("HTTP/1.1 400 Bad Request\r\nConnection: close\r\nContent-Length: 0\r\n\r\n");
   154	  });
   155	
   156	  await new Promise<void>((resolve, reject) => {
   157	    server.once("error", reject);
   158	    const onListening = (): void => {
   159	      server.off("error", reject);
   160	      resolve();
   161	    };
   162	    if (options.host === undefined) {
   163	      server.listen(config.port, onListening);
   164	    } else {
   165	      server.listen(config.port, options.host, onListening);
   166	    }
   167	  });
   168	
   169	  const shutdownTimeoutMs = options.shutdownTimeoutMs ?? 5000;
   170	  let closing: Promise<void> | undefined;
   171	
   172	  return {
   173	    server,
   174	    port: (server.address() as AddressInfo).port,
   175	    close() {
   176	      closing ??= new Promise<void>((resolve, reject) => {
   177	        const timer = setTimeout(() => server.closeAllConnections(), shutdownTimeoutMs);
   178	        timer.unref();
   179	        server.close((err) => {
   180	          clearTimeout(timer);
   181	          if (err) reject(err);
   182	          else resolve();
   183	        });
   184	        server.closeIdleConnections();
   185	      });
   186	      return closing;
   187	    },
   188	  };
   189	}
{
  "name": "syncbox",
  "version": "0.1.0",
  "private": true,
  "description": "Self-hosted file storage with sync: HTTP server + CLI client",
  "type": "module",
  "engines": {
    "node": ">=20 <21"
  },
  "scripts": {
    "build": "tsc -p tsconfig.build.json",
    "build:test": "tsc -p tsconfig.json",
    "test": "node --test --test-reporter=spec dist/test/",
    "start": "node dist/src/main.js"
  },
  "devDependencies": {
    "@types/node": "~20.19.43",
    "typescript": "~5.9.3"
  }
}
#!/usr/bin/env bash
# Builds the test image and runs the whole test suite inside Docker (via
# docker compose). Exits non-zero if any test fails.
set -euo pipefail

repo="$(cd "$(dirname "${BASH_SOURCE[0]}")" && pwd)"

exec docker compose --project-directory "$repo" -f "$repo/compose.yaml" \
  run --rm --build -T test
# syntax=docker/dockerfile:1

# --- dependencies (incl. dev: TypeScript, type definitions) ---------------
FROM node:20-bookworm-slim AS deps
WORKDIR /app
COPY package.json package-lock.json ./
RUN npm ci --no-audit --no-fund

# --- compile server sources -----------------------------------------------
FROM deps AS build
COPY tsconfig.json tsconfig.build.json ./
COPY src ./src
RUN npm run build

# --- test image: compiled sources + compiled tests ------------------------
FROM build AS test
COPY test ./test
RUN npm run build:test
CMD ["npm", "test", "--silent"]

# --- runtime image: production dependencies and compiled server only ------
FROM node:20-bookworm-slim AS server
ENV NODE_ENV=production
WORKDIR /app
COPY package.json package-lock.json ./
RUN npm ci --omit=dev --no-audit --no-fund && npm cache clean --force
COPY --from=build /app/dist/src ./dist/src
USER node
EXPOSE 8080
CMD ["node", "dist/src/main.js"]
# All Docker plumbing for Syncbox lives here. The run-server / run-tests
# wrappers only export the variables below and call `docker compose`.
#
#   SYNCBOX_HOST_DATA_DIR  host directory bind-mounted as the server's data dir
#                          (absolute path; default ./data in the repo)
#   SYNCBOX_PORT           port the server listens on, both in the container
#                          and on the host (default 8080)
#   SYNCBOX_PUBLISH_ADDR   host interface the port is published on
#                          (default 127.0.0.1; set 0.0.0.0 to expose on the LAN)
#   SYNCBOX_UID/GID        user the server runs as, so files in the data dir
#                          are owned by the invoking host user (default 1000)

services:
  server:
    # Fixed tag: run-server uses a separate compose project per port, and
    # they should all share one image rather than each building its own.
    image: syncbox-server:local
    build:
      context: .
      target: server
    init: true
    # Docker's default bridge: no per-project network has to be created, so
    # several servers (on different ports) can be started concurrently.
    network_mode: bridge
    user: "${SYNCBOX_UID:-1000}:${SYNCBOX_GID:-1000}"
    environment:
      SYNCBOX_DATA_DIR: /data
      SYNCBOX_PORT: "${SYNCBOX_PORT:-8080}"
    ports:
      - "${SYNCBOX_PUBLISH_ADDR:-127.0.0.1}:${SYNCBOX_PORT:-8080}:${SYNCBOX_PORT:-8080}"
    volumes:
      - type: bind
        source: "${SYNCBOX_HOST_DATA_DIR:-./data}"
        target: /data
        bind:
          create_host_path: true

  test:
    build:
      context: .
      target: test
    profiles: [test]
    init: true
    # Tests only talk to servers they start themselves on loopback.
    network_mode: none

  # Toolbox for dependency management without Node on the host, e.g.
  #   docker compose run --rm dev npm install --save-dev <pkg>
  dev:
    image: node:20-bookworm-slim
    profiles: [dev]
    working_dir: /app
    user: "${SYNCBOX_UID:-1000}:${SYNCBOX_GID:-1000}"
    environment:
      npm_config_cache: /tmp/.npm
      npm_config_update_notifier: "false"
    volumes:
      - type: bind
        source: .
        target: /app
Продолжаем проект Syncbox (тикеты 1-2 — каркас сервера и happy path для PUT/GET блоба — уже сделаны в этом же репозитории). Тикет 3: список блобов.

Полная спецификация — в файлах SYNCBOX-SPEC.md и syncbox-openapi.yaml в корне этого репозитория — прочитай перед началом, если нужно освежить детали.

Нужно реализовать:

- GET /blobs — вернуть 200 и JSON-массив объектов {"key", "size", "sha256", "modified_at"} для всех блобов, хранящихся на сервере.
- size — размер в байтах, sha256 — хеш содержимого в hex, modified_at — время последнего изменения в ISO 8601 UTC.
- key — POSIX-путь относительно корня хранилища, включая вложенные директории (например docs/readme.txt), если такие блобы есть на диске.
- Пустое хранилище — пустой массив [], это не ошибка.

Границы этого тикета:

- DELETE /blobs/{key} — отдельный будущий тикет, в этот не входит.
- Защита от directory traversal в key и атомарность записи при параллельных PUT — тоже отдельные будущие тикеты (если ещё не реализованы в текущем коде).

Не реализовывай перечисленное выше заранее — не входит в объём этого тикета.

Сервер по-прежнему должен исполняться в Docker-контейнере через docker compose — не переделывай эту часть, если она уже работает, расширяй по необходимости.

Библиотеки и внутреннее устройство — на твоё усмотрение, как и в предыдущих тикетах.

Версия языка в этом проекте зафиксирована: Node.js 20, базовый Docker-образ node:20-bookworm-slim (FROM node:20-bookworm-slim в Dockerfile). Не меняй версию языка и базовый образ.

