  });

  it("HEAD reports the blob size without a body", async () => {
    await request("PUT", "/blobs/get/head.txt", "12345");
    const res = await request("HEAD", "/blobs/get/head.txt");
    assert.equal(res.status, 200);
    assert.equal(res.headers["content-length"], "5");
    assert.equal(res.body, "");
    assert.equal((await request("HEAD", "/blobs/get/nope")).status, 404);
  });

  it("rejects other methods on /blobs/{key} with 405", async () => {
    const res = await request("POST", "/blobs/get/head.txt", "x");
    assert.equal(res.status, 405);
    assert.equal(res.headers.allow, "GET, HEAD, PUT, DELETE");
    assert.equal((await request("GET", "/blobs/get/head.txt")).body, "12345");
  });

  it("DELETE removes a blob and answers 204 with no body", async () => {
    assert.equal((await request("PUT", "/blobs/del/0", "x")).status, 201);
    const res = await request("DELETE", "/blobs/del/0");
    assert.equal(res.status, 204);
    assert.equal(res.body, "");
    assert.equal((await request("GET", "/blobs/del/0")).status, 404);
    assert.ok(!(await list()).some((b) => b.key === "del/0"));
    // Deleting again: there is nothing left to delete.
    assert.equal((await request("DELETE", "/blobs/del/0")).status, 404);
  });

  it("DELETE accepts the same key spellings as PUT", async () => {
    assert.equal((await request("PUT", "/blobs/del/caf%C3%A9/menu.txt", "x")).status, 201);
    assert.equal((await request("DELETE", "/blobs/del%2Fcaf%C3%A9%2Fmenu.txt")).status, 204);
    assert.equal((await request("GET", "/blobs/del/caf%C3%A9/menu.txt")).status, 404);
  });

  it("DELETE answers 404 for keys that are not blobs and leaves other blobs alone", async () => {
    assert.equal((await request("PUT", "/blobs/del/dir/file.txt", "keep")).status, 201);
    for (const path of [
      "/blobs/del/missing",
      "/blobs/no/such/dir/file",
      "/blobs/del/dir", // a directory of another key, not a blob
      "/blobs/del/dir/file.txt/child", // a path below an existing blob
      `/blobs/${"a/".repeat(2100)}a`, // longer than the file system allows
    ]) {
      const res = await request("DELETE", path);
      assert.equal(res.status, 404, path.slice(0, 60));
    }
    assert.equal((await request("GET", "/blobs/del/dir/file.txt")).body, "keep");
  });

  it("DELETE answers 400 for invalid keys and removes nothing", async () => {
    await writeFile(join(root, "outside"), "x");
    assert.equal((await request("PUT", "/blobs/del/inside", "x")).status, 201);
    const before = await readdir(root);
    for (const path of [
      "/blobs/",
      "/blobs/../outside",
      "/blobs/del/../../outside",
      "/blobs/%2e%2e/outside",
      "/blobs/%2E%2E%2Foutside",
      "/blobs//etc/passwd",
      "/blobs/%2Fetc%2Fpasswd",
      "/blobs/del//inside",
      "/blobs/del/inside/",
      "/blobs/./del/inside",
      "/blobs/%00",
      "/blobs/%",
      "/blobs/%zz",
      "/blobs/%FF",
      "/blobs/%ED%A0%80",
      `/blobs/${"a".repeat(256)}`,
    ]) {
      const res = await request("DELETE", path);
      assert.equal(res.status, 400, path);
    }
    assert.equal(await rawStatus("DELETE", Buffer.concat([Buffer.from("/blobs/"), Buffer.from([0xff, 0xfe])])), 400);
